source.loginUrl:
function login() {
  const {
    source,
    java
  } = this;
  let loginInfo = source.getLoginInfoMap() || {};
  let loginName = loginInfo["账号"] || "";
  let password = loginInfo["密码"] || "";
  let isAutoReg = loginName == "" || password == "";
  let param = {
    login_name: loginName,
    passwd: password,
  }
  let url = isAutoReg ? this.auto_reg() : this.Login(param);
  let res = java.ajax(url);
  res = this.decrypt(res);
  if (res.code != "100000") {
    java.toast(res.tip);
    java.log(res.tip);
    throw new Error(res.tip)
  }
  let data = this.getData();
  data.login_token = res.data.login_token;
  data.account = res.data.reader_info.account;
  this.setData(data);
  let logText = `${isAutoReg ? "游客账号" : "账号" + loginName} 登录成功`;
  // java.log(logText);
  java.toast(logText);
  Packages.java.lang.Thread.sleep(500);
}

/**
 * 签到
 */
function bonus() {
  let data = this.getData();
  if (!data["login_token"] || !data["account"]) {
    // java.log("请先登录");
    java.toast("请先登录");
    return
  }
  let url = this.URL(`/reader/get_daily_task_bonus`, {
    task_type: 1
  })
  let res = java.ajax(url);
  res = this.decrypt(res);
  if (res.code == "100000") {
    java.toast(`签到成功 获得${res.data.bonus.hlb || 0}代币`)
    // java.log(`签到成功 获得${res.data.bonus.hlb}代币`)
  }
}

/**
 * 获取剩余代币数量，**类型data中仅存在prop_info**
 */
function prop_info() {
  let url = this.URL(`/reader/get_prop_info`)
  let res = java.ajax(url);
  res = this.decrypt(res);
  if (res.code == "100000") {
    //java.log(`当前有${res.data.prop_info.rest_hlb}代币`)
    java.toast(`当前有${res.data.prop_info.rest_hlb}代币`)
  }
}

function logout() {
  source.removeLoginInfo();
  this.setData({});
  java.toast('账号已退出登录！')
}

